var state=document.getElementById("replay-chart-state"), status=document.getElementById("replay-live-status"), position=document.getElementById("replay-position"), mark=document.getElementById("replay-mark"), markLabel=document.getElementById("replay-mark-label"), progress=document.getElementById("replay-progress-text"), stageLabel=document.getElementById("replay-stage-label"), stageTitle=document.getElementById("replay-stage-title"), stageCopy=document.getElementById("replay-stage-copy"), summary=document.getElementById("replay-outcome");
