 [hi,(hi+lo)/2,lo].forEach(function(v){var yy=y(v);parts.push('<line class="replay-grid" x1="'+left+'" y1="'+yy+'" x2="'+(width-right)+'" y2="'+yy+'"/><text class="replay-axis-label" x="'+(left-9)+'" y="'+(yy+4)+'" text-anchor="end">'+price(v)+'</text>')});
 visible.forEach(function(c,i){var x=left+i*slot+slot/2,up=c.c>=c.o,color=up?"#ff8b8f":"#56d9ed",yHigh=y(c.h),yLow=y(c.l),yo=y(c.o),yc=y(c.c),rectY=Math.min(yo,yc),rectH=Math.max(1.5,Math.abs(yo-yc));parts.push('<g><title>Elapsed '+(c.t>=0?"+":"")+c.t+' min · O '+price(c.o)+' · H '+price(c.h)+' · L '+price(c.l)+' · C '+price(c.c)+'</title><line x1="'+x+'" y1="'+yHigh+'" x2="'+x+'" y2="'+yLow+'" stroke="'+color+'" stroke-width="1.5"/><rect x="'+(x-body/2)+'" y="'+rectY+'" width="'+body+'" height="'+rectH+'" rx="1" fill="'+color+'"/></g>')});
