 var tickIndexes=[0,Math.floor((visible.length-1)/2),visible.length-1].filter(function(v,i,a){return a.indexOf(v)===i});tickIndexes.forEach(function(i){var x=left+i*slot+slot/2,t=data.candles[i].t,label=(t===0?"Entry":(t>0?"+":"")+t+" min");parts.push('<text class="replay-axis-label" x="'+x+'" y="'+(height-17)+'" text-anchor="middle">'+escaped(label)+'</text>')});
