 setText("replay-mark-title",complete?"Recorded gross P&L":"Current gross mark");
 mark.textContent=complete?money(outcome.grossBRL)+" gross":inTrade?money(mtm)+" gross":"—";markLabel.textContent=complete?"Recorded gross result; C30 costs are shown below.":inTrade?"Open mark at the latest visible M5 close; gross, before costs.":"No position is open in the visible sequence.";
