function init(){enableControls(false);fetch("data/replay/two-contract-win.json").then(function(r){if(!r.ok)throw Error("Replay data could not be loaded.");return r.json()}).then(function(d){data=d;if(!data.candles||data.candles.length!==21||data.contracts!==2)throw Error("Replay data validation failed.");slider.max=String(data.candles.length-1);current=data.entryIndex-1;render();enableControls(true)}).catch(fail)}
root.querySelectorAll("[data-replay-action]").forEach(function(button){button.addEventListener("click",function(){var a=button.dataset.replayAction;if(a==="play")play();else if(a==="pause")stop();else if(a==="restart"){stop();outcome=null;current=data.entryIndex-1;render()}else if(a==="previous"){stop();go(current-1)}else if(a==="next"){stop();go(current+1)}else if(a==="entry"){stop();go(data.entryIndex)}else if(a==="exit"){stop();go(data.exitIndex)}})});
